<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Conway's Game of Life</title>
    <style>
        :root {
            --bg-color: #121214;
            --grid-bg: #1e1e24;
            --cell-alive: #39ff14; /* Neon Green */
            --text-color: #f0f0f5;
            --button-hover: #ffffff1a;
        }

        body {
            margin: 0;
            padding: 2rem;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
        }

        h1 { margin-bottom: 1rem; font-weight: 300; letter-spacing: 2px; text-transform: uppercase; color: #888;}

        /* Layout & Grid */
        .game-container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 1.5rem;
        }

        canvas#life {
            background-color: var(--grid-bg);
            border-radius: 4px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6), inset 0 0 15px #000;
            /* Ensure at least 400x400 CSS pixels */
            width: 600px !important; 
            height: 600px !important;

            /* Pixelated look for crisp cells */
            image-rendering: -moz-crisp-edges;
            image-rendering: -webkit-crisp-edges;
            image-rendering: pixelated;
        }

        .controls {
            display: flex;
            gap: 1rem;
            background: #252530;
            padding: 0.8rem 1.5rem;
            border-radius: 12px;
            box-shadow: inset 0 1px 4px rgba(255,255,255,0.1);
        }

        button {
            background-color: #3e3e4a;
            color: white;
            border: none;
            padding: 0.6rem 1.2rem;
            font-size: 0.9rem;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s ease, transform 0.1s ease;
            text-transform: uppercase;
            letter-spacing: 1px;
            outline: none;
        }

        button:hover { background-color: #4e4e5c; transform: translateY(-1px); }
        button:active { transform: translateY(0); box-shadow: inset 0 2px 8px rgba(0,0,0,0.3); }

        /* Playful Colors */
        #play.btn-active { background-color: var(--cell-alive) !important; color: black !important; font-weight: bold;}
    </style>
</head>
<body>

<div class="game-container">
    <h1>LIFE SIMULATION</h1>

    <!-- Canvas element -->
    <canvas id="life"></canvas>

    <!-- Control buttons -->
    <div class="controls">
        <button id="step">Step</button>
        <button id="play" class="btn">Play / Stop</button>
        <button id="random">Randomize</button>
        <button id="clear">Clear Grid</button>
    </div>
</div>

<script>
/** 
 * Conway's Game of Life - Implementation
 */

// Configuration: Minimum 40x40, Canvas >= 400 CSS pixels.
const WIDTH = 64; // Cell count width (>= 40)
const HEIGHT = 64; // Cell count height (>= 40)
const CELL_SIZE = 15;

// Internal Canvas Resolution to ensure pixelated sharpness and >= 400px CSS size
const CANVAS_WIDTH_PX = WIDTH * CELL_SIZE; 
const CANVAS_HEIGHT_PX = HEIGHT * CELL_SIZE;

// DOM Elements
const canvas = document.getElementById('life');
const ctx = canvas.getContext('2d', { willReadFrequently: true }); // Hint for performance
const btnStep = document.getElementById('step');
const btnPlay = document.getElementById('play');
const btnRandom = document.getElementById('random');
const btnClear = document.getElementById('clear');

// Set Canvas Attributes (Resolution) and CSS Size
canvas.width = CANVAS_WIDTH_PX;
canvas.height = CANVAS_HEIGHT_PX;
// CSS size set via ID style in stylesheet, but ensure it is >= 400x400. 
// Styles above enforce width:600px !important which satisfies the requirement.

// State Buffers (Double Buffering for simultaneous updates)
let grid = new Uint8Array(WIDTH * HEIGHT); // Current generation
let nextGrid = new Uint8Array(WIDTH * HEIGHT); // Next generation calculation

// Helper to access 1D array index from x,y coordinates
const idx = (x, y) => { if(x<0||y<0||x>=WIDTH||y>=HEIGHT) return -1; return y * WIDTH + x; };

// --- API Object ---
window.life = {
    // Dimensions in cells
    w: WIDTH, 
    h: HEIGHT, 

    // Get cell value (0 or 1). Returns 0 for out-of-bounds.
    get(x, y) {
        const i = idx(x, y);
        return (i === -1) ? 0 : grid[i];
    },

    // Set cell value (alive/dead) and redraw immediately? 
    // For programmatic seeding during the app's lifetime, it feels natural to update.
    set(x, y, v) {
        const i = idx(x, y);
        if (i !== -1 && grid[i] !== v) {
            grid[i] = v ? 1 : 0;
            draw(); // Redraw on API usage for visual feedback consistency
        }
    },

    // Advance exactly one generation and redraw
    step: function() {
        calculateNextGen();

        // Swap buffers (simultaneous update achieved by using separate buffer)
        let temp = grid;
        grid = nextGrid;
        nextGrid = temp;

        draw();
    },

    // Set every cell dead and redraw
    clear: function() {
        for(let i=0; i<grid.length; i++) grid[i] = 0;
        draw();
    }
};

// --- Simulation Logic (B3/S23) ---
function countNeighbors(x, y) {
    let sum = 0;
    // Iterate over neighbors relative to x,y
    for(let dy = -1; dy <= 1; dy++) {
        for(let dx = -1; dx <= 1; dx++) {
            if(dx === 0 && dy === 0) continue; // Skip self

            const nx = x + dx;
            const ny = y + dy;

            // Edges are dead (out of bounds returns 0 implicitly in grid access logic, 
            // but here we check indices to avoid array errors when accessing 'grid' directly).
            if(nx >= 0 && nx < WIDTH && ny >= 0 && ny < HEIGHT) {
                sum += grid[idx(nx, ny)];
            }
        }
    }
    return sum;
}

function calculateNextGen() {
    // We write to nextGrid based on current 'grid' state. 
    // This ensures simultaneous updates (no cell sees a neighbor that has already been updated).

    let changed = false;
    for(let y=0; y<HEIGHT; y++) {
        for(let x=0; x<WIDTH; x++) {
            const myIdx = idx(x,y);

            // Optimization: if cell is dead, neighbors count determines birth. 
            // If cell is alive, survival depends on 2 or 3.
            const state = grid[myIdx];
            const nCount = countNeighbors(x, y);

            let nextState = 0;

            if (state === 1) {
                // Live Cell: Survives with 2 or 3 neighbors
                nextState = (nCount === 2 || nCount === 3) ? 1 : 0;
            } else {
                // Dead Cell: Becomes alive with exactly 3 neighbors
                nextState = (nCount === 3) ? 1 : 0;
            }

            nextGrid[myIdx] = nextState;
        }
    }
}

// --- Rendering ---
function draw() {
    // Clear canvas background
    ctx.fillStyle = '#2a2a35'; // Slightly lighter than grid bg for contrast? Or match CSS. 
    ctx.fillRect(0, 0, CANVAS_WIDTH_PX, CANVAS_HEIGHT_PX);

    // Draw Cells (using path for speed/rounding)
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--cell-alive').trim();

    let hasChanged = false; // Simple tracking if needed? Not strictly necessary.

    // Loop and draw
    const aliveCellsCount = grid.reduce((a,b)=>a+b,0);

    for(let y=0; y<HEIGHT; y++) {
        for(let x=0; x<WIDTH; x++) {
            if(grid[idx(x,y)] === 1) {
                ctx.fillRect(
                    Math.floor(x * CELL_SIZE), 
                    Math.floor(y * CELL_SIZE), 
                    CELL_SIZE, 
                    CELL_SIZE
                );
            }
        }
    }

    // Optional: Draw grid lines (faint) for aesthetics on dark theme?
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    const stepX = CANVAS_WIDTH_PX % WIDTH ? 0 : CELL_SIZE; 
    if(stepX === 0 && WIDTH <= 64) { // Only draw grid lines if not pixel-perfect alignment issue
       for(let x=0; x<=WIDTH; x++) {
           ctx.beginPath();
           ctx.moveTo(x*CELL_SIZE, 0);
           ctx.lineTo(x*CELL_SIZE, CANVAS_HEIGHT_PX);
           ctx.stroke();
       }
       for(let y=0; y<=HEIGHT; y++) {
           ctx.beginPath();
           ctx.moveTo(0, y*CELL_SIZE);
           ctx.lineTo(CANVAS_WIDTH_PX, y*CELL_SIZE);
           ctx.stroke();
       }
    }
}

// --- Interaction & Controls ---

let isRunning = false;
let intervalId = null;

function togglePlay() {
    if (isRunning) {
        clearInterval(intervalId);
        btnPlay.textContent = "Play / Stop";
        btnPlay.classList.remove('btn-active');
        isRunning = false;
    } else {
        // Start loop (100ms per generation approx)
        intervalId = setInterval(() => window.life.step(), 100);
        btnPlay.textContent = "Stop Running";
        btnPlay.classList.add('btn-active');
        isRunning = true;
    }
}

function seedRandom() {
    // Randomize cells with a probability (e.g., 30% chance to be alive)
    for(let y=0; y<HEIGHT; y++) {
        for(let x=0; x<WIDTH; x++) {
            window.life.set(x, y, Math.random() < 0.3 ? 1 : 0);
        }
    }
}

// Mouse Painting
let isMouseDown = false;

function getMousePos(e) {
    const rect = canvas.getBoundingClientRect();
    // Note: CSS width/height might differ from internal resolution due to scaling. 
    // We need coordinates relative to the drawing buffer (1000x1000).
    const scaleX = CANVAS_WIDTH_PX / rect.width;
    const scaleY = CANVAS_HEIGHT_PX / rect.height;

    return {
        x: Math.floor((e.clientX - rect.left) * scaleX),
        y: Math.floor((e.clientY - rect.top) * scaleY)
    };
}

function handleMouseAction(e) {
    if (isMouseDown) {
        const pos = getMousePos(e);

        // Convert screen pixels to grid coordinates
        const gx = Math.floor(pos.x / CELL_SIZE);
        const gy = Math.floor(pos.y / CELL_SIZE);

        window.life.set(gx, gy, 1); // Paint alive on drag (for better control)
    }
}

// Event Listeners for Controls
btnStep.addEventListener('click', () => { if(!isRunning) window.life.step(); });
btnPlay.addEventListener('click', togglePlay);
btnRandom.addEventListener('click', seedRandom);
btnClear.addEventListener('click', () => { window.life.clear(); });

// Mouse Events on Canvas
canvas.addEventListener('mousedown', (e) => { isMouseDown = true; handleMouseAction(e); draw(); }); // Draw immediately on click start too?
// Note: If user clicks and holds, they want to paint continuously. 
// On mousedown we trigger once so they don't just toggle instantly if not dragging.

canvas.addEventListener('mouseup', () => { isMouseDown = false; });
canvas.addEventListener('mouseleave', () => { isMouseDown = false; }); // Safety for drag outside

window.addEventListener('mousemove', (e) => { 
    if(isMouseDown && e.buttons === 1) { handleMouseAction(e); draw(); } // Draw continuously while dragging
});

// Initial Render and API Setup
draw();

</script>
</body>
</html>
